function btn(text,act,style='secondary',attrs=''){if(!canAction(act))return '';return `<button type="button" class="button ${style}" data-action="${act}" ${attrs}>${text}</button>`} function head(title,subtitle,actions=''){return `<div class="page-head"><div><div class="eyebrow">Gestión de almacén</div><h1>${title}</h1><p>${subtitle}</p></div><div class="actions">${actions}</div></div>`}const stockState=p=>p.stock<=0?'Agotado':p.stock<=p.min?'Stock bajo':'Disponible';const badge=p=>`<span class="badge ${p.stock<=0?'out':p.stock<=p.min?'warning':''}">${stockState(p)}</span>`;const typeName=t=>({entrada:'Entrada',salida:'Salida',devolucion:'Devolución',ajuste:'Ajuste',traslado:'Traslado',merma:'Merma'})[t]||t;const signed=m=>['salida','merma'].includes(m.type)?'-':m.type==='traslado'?'':m.type==='ajuste'?'':'+';const changeStr=m=>`${signed(m)}${fmt(m.qty)} ${esc(m.unit)}`;const productOptions=(selected='')=>data.products.map(p=>`<option value="${esc(p.id)}" ${p.id===selected?'selected':''}>${esc(p.code)} · ${esc(p.name)}</option>`).join('');const orderOptions=(selected='')=>'<option value="">Sin orden</option>'+data.orders.map(o=>`<option value="${esc(o.code)}" ${o.code===selected?'selected':''}>${esc(o.code)} · ${esc(o.name)}</option>`).join('');const options=(a,v)=>a.map(x=>`<option ${x===v?'selected':''}>${esc(x)}</option>`).join('');
