function operationsHome(){const ps=data.products,low=ps.filter(p=>p.stock<=p.min),warehouse=role()==='almacen';return head('Hola, '+esc(currentUser?.displayName||'Operario'),warehouse?'Registra entradas y salidas desde el almacén.':'Retira o devuelve material para una orden de producción.')+`<div class="panel hero"><div><div class="eyebrow">OPERACIÓN RÁPIDA</div><h2>Escanea el material</h2><p>Identifica el código y confirma la cantidad. No necesitas escribir el producto.</p></div>${btn(ico('scan')+' Abrir escáner','scan','')}</div><div class="ops-actions">${warehouse?btn(ico('plus')+' Registrar entrada','entry','')+btn(ico('moves')+' Registrar salida','exit'):btn(ico('moves')+' Retirar material','exit','')+btn(ico('moves')+' Devolver material','return')}${btn('Ver inventario','quick-inventory')}${warehouse?btn('Imprimir etiquetas','go-labels'):''}</div><div class="metrics ops-metrics"><div class="panel metric"><div class="metric-icon">${ico('inventory')}</div><div><div class="metric-label">Materiales</div><strong>${fmt(ps.length)}</strong><small>Referencias registradas</small></div></div><div class="panel metric"><div class="metric-icon warn">${ico('alert')}</div><div><div class="metric-label">Stock bajo</div><strong>${fmt(low.length)}</strong><small>Requieren atención</small></div></div><div class="panel metric"><div class="metric-icon">${ico('moves')}</div><div><div class="metric-label">Movimientos</div><strong>${fmt(data.movements.length)}</strong><small>Registrados en historial</small></div></div></div><div class="panel"><div class="panel-head"><div><h2>Últimos movimientos</h2><p>Consulta las operaciones recientes.</p></div><button class="text-button" data-go="moves">Ver historial</button></div>${movementRows(data.movements.slice(0,5))}</div>`}
