function inventoryTable(){const ps=filtered();return `<div class="table-wrap inventory-wrap"><table class="table inventory-table"><thead><tr><th>Código</th><th>Material</th><th>Stock</th><th>Mínimo</th><th>Ubicación</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>${ps.map(p=>`<tr><td class="code">${esc(p.code)}</td><td class="name material"><span class="product-name">${esc(p.name)}</span><span class="sub">${esc(p.category)} · ${esc(p.detail)}</span></td><td data-label="Stock"><b>${fmt(p.stock)}</b> ${esc(p.unit)}</td><td data-label="Mínimo">${fmt(p.min)} ${esc(p.unit)}</td><td data-label="Ubicación"><span class="tag">${esc(p.location||'—')}</span></td><td data-label="Estado">${badge(p)}</td><td><div class="row-actions">${btn('Ver','detail','small secondary',`data-id="${esc(p.id)}"`)}${btn('Mov.','move','small secondary',`data-id="${esc(p.id)}"`)}${btn(ico('labels'),'one-label','small secondary',`data-id="${esc(p.id)}" aria-label="Etiqueta de ${esc(p.name)}"`)}</div></td></tr>`).join('')}</tbody></table>${ps.length?'':'<div class="empty">No se encontraron materiales.</div>'}</div><p class="section-gap" style="font-size:13px">${ps.length} de ${data.products.length} materiales</p>`}
function inventory(){return head('Inventario de materiales','Consulta, identifica y administra cada material de tu imprenta.',btn('Exportar CSV','csv-products')+btn(ico('plus')+' Nuevo material','new-product',''))+`<div class="panel"><div class="filters"><input id="search" placeholder="Buscar nombre, código, ubicación…" value="${esc(search)}" aria-label="Buscar materiales"><select id="category" aria-label="Categoría"><option value="">Todas las categorías</option>${options(categories,cat)}</select><select id="status" aria-label="Estado"><option value="">Todos los estados</option>${options(['Disponible','Stock bajo','Agotado','Alerta'],status)}</select>${btn('Limpiar filtros','clear-filters')}</div><div id="inventory-table">${inventoryTable()}</div></div>`}
function moves(){let m=data.movements.filter(x=>!moveFilter||x.type===moveFilter);return head('Historial de movimientos','Trazabilidad de las entradas, salidas, ajustes y traslados.',btn('Exportar CSV','csv-moves')+btn('+ Movimiento','move',''))+`<div class="panel"><div class="filters"><select id="move-filter"><option value="">Todos los movimientos</option>${['entrada','salida','devolucion','ajuste','traslado','merma'].map(t=>`<option value="${t}" ${t===moveFilter?'selected':''}>${typeName(t)}</option>`).join('')}</select></div><div class="table-wrap"><table class="table"><thead><tr><th>Fecha</th><th>Tipo</th><th>Material</th><th>Cantidad</th><th>Orden</th><th>Responsable / nota</th></tr></thead><tbody>${m.map(x=>`<tr><td>${date(x.when)}</td><td><span class="badge ${['salida','merma'].includes(x.type)?'warning':'blue'}">${typeName(x.type)}</span></td><td class="name"><b>${esc(x.name)}</b><span class="sub">${esc(x.code)}</span></td><td>${changeStr(x)}</td><td>${esc(x.order||'—')}</td><td class="name">${esc(x.operator||'Operador')}<span class="sub">${esc(x.note)}</span></td></tr>`).join('')}</tbody></table>${m.length?'':'<div class="empty">Sin movimientos para este filtro.</div>'}</div></div>`}
function labels(){return head('Etiquetas e identificación','Genera códigos de barras Code 128 o QR listos para imprimir y pegar en tus materiales.')+`<div class="label-layout"><div class="panel"><h2>Configurar etiquetas</h2><p>Selecciona los materiales y el formato.</p><div class="section-gap"><label class="field">Tipo de código<select id="label-type"><option value="barcode" ${labelType==='barcode'?'selected':''}>Código de barras (Code 128)</option><option value="qr" ${labelType==='qr'?'selected':''}>Código QR</option></select></label><div class="form-grid"><label class="field">Tamaño<select id="label-size"><option ${labelSize==='70x40'?'selected':''} value="70x40">70 × 40 mm</option><option ${labelSize==='60x35'?'selected':''} value="60x35">60 × 35 mm</option><option ${labelSize==='90x50'?'selected':''} value="90x50">90 × 50 mm</option></select></label><label class="field">Copias por material<input id="label-qty" type="number" min="1" max="30" value="${labelQty}"></label></div><div class="panel-head"><h3>Materiales</h3><button class="text-button" data-action="label-all">${labelIds.size===data.products.length?'Deseleccionar todos':'Seleccionar todos'}</button></div><div class="check-list">${data.products.map(p=>`<label class="check-row"><input class="label-check" type="checkbox" value="${esc(p.id)}" ${labelIds.has(p.id)?'checked':''}><span><b>${esc(p.name)}</b><small class="sub">${esc(p.code)}</small></span></label>`).join('')||'<div class="empty">Añade un material primero.</div>'}</div><div class="notice">Imprime al 100% de escala, sin encabezados del navegador. Conserva espacio blanco alrededor del código.</div>${btn(ico('print')+' Imprimir / guardar PDF','print','')}</div></div><div class="panel"><div class="panel-head"><div><h2>Vista previa</h2><p id="label-count"></p></div></div><div id="label-preview" class="label-preview"></div></div></div>`}
function labelElements(container,limit){container.innerHTML='';let count=0;let [w,h]=labelSize.split('x');for(const p of data.products.filter(p=>labelIds.has(p.id))){for(let i=0;i<labelQty&&count<limit;i++,count++){const el=document.createElement('div');el.className='label';el.style.width=w+'mm';el.style.height=h+'mm';el.innerHTML=`<b>${esc(p.name)}</b>${labelType==='qr'?'<canvas></canvas>':'<svg></svg>'}<small>${esc(p.code)} · ${esc(p.location||'Sin ubicación')}</small>`;container.append(el);if(labelType==='qr'){try{QR.toCanvas(el.querySelector('canvas'),p.code,{width:120,margin:2,errorCorrectionLevel:'M'})}catch{el.querySelector('canvas').replaceWith(document.createTextNode('QR no disponible'))}}else{try{JsBarcode(el.querySelector('svg'),p.code,{format:'CODE128',displayValue:false,height:48,width:1.65,margin:9})}catch{el.querySelector('svg').replaceWith(document.createTextNode('Código no válido'))}}}}}
function drawLabels(){let n=data.products.filter(p=>labelIds.has(p.id)).length*labelQty;$('#label-count').textContent=`${n} etiquetas · ${labelType==='qr'?'QR':'Code 128'}`;labelElements($('#label-preview'),12);if(!n)$('#label-preview').innerHTML='<div class="empty">Selecciona uno o más productos para ver sus etiquetas.</div>';else if(n>12)$('#label-preview').insertAdjacentHTML('beforeend',`<p>Vista de las primeras 12 de ${n} etiquetas.</p>`)}
function orders(){return head('Órdenes de trabajo','Consulta las órdenes y registra el material utilizado.',btn('+ Nueva orden','new-order',''))+`<div class="card-grid">${data.orders.map(o=>{const cost=data.movements.filter(m=>m.order===o.code).reduce((s,m)=>s+(['salida','merma'].includes(m.type)?m.qty*m.cost:m.type==='devolucion'?-m.qty*m.cost:0),0);return `<div class="panel"><span class="badge ${o.state==='Finalizada'?'':'blue'}">${esc(o.state)}</span><div class="code section-gap">${esc(o.code)}</div><h2>${esc(o.name)}</h2><p>${esc(o.client||'Sin cliente')}</p>${finance()?`<div class="big-number">${money(cost)}</div><p>Consumo neto · Presupuesto ${money(o.budget)}</p>`:`<p class="section-gap">${data.movements.filter(m=>m.order===o.code).length} movimientos registrados</p>`}<div class="actions">${btn('Editar','edit-order','secondary',`data-id="${esc(o.id)}"`)}${btn('Registrar consumo','order-use','',`data-id="${esc(o.id)}"`)}</div></div>`}).join('')||'<div class="panel empty">No hay órdenes registradas.</div>'}</div>`}
function locations(){let groups=Object.create(null);for(const p of data.products)(groups[p.location||'Sin ubicación']??=[]).push(p);return head('Ubicaciones de almacén','Encuentra rápidamente los productos por estante, zona o depósito.')+`<div class="card-grid">${Object.entries(groups).map(([k,p])=>`<div class="panel"><span class="badge neutral">ESTANTE / ZONA</span><div class="big-number">${esc(k)}</div><p>${p.length} materiales registrados</p><div class="section-gap">${p.map(x=>`<div class="alert-item"><div class="item-info"><b>${esc(x.name)}</b><small>${esc(x.code)}</small></div><b>${fmt(x.stock)} ${esc(x.unit)}</b></div>`).join('')}</div></div>`).join('')||'<div class="panel empty">No hay materiales asignados.</div>'}</div>`}
function suppliers(){return head('Proveedores','Organiza tus contactos y materiales asociados.',btn('+ Nuevo proveedor','new-supplier',''))+`<div class="card-grid">${data.suppliers.map(s=>`<div class="panel"><div class="metric-icon">${ico('suppliers')}</div><h2 class="section-gap">${esc(s.name)}</h2><p>${esc(s.notes||'Sin notas')}</p><p class="section-gap">${esc(s.phone||'Sin teléfono')}<br>${esc(s.email||'Sin correo')}</p><div class="big-number">${data.products.filter(p=>p.supplier===s.name).length} <span style="font-size:15px;font-weight:400">materiales</span></div>${btn('Editar proveedor','edit-supplier','secondary',`data-id="${esc(s.id)}"`)}</div>`).join('')||'<div class="panel empty">No hay proveedores.</div>'}</div>`}
function reports(){let val=data.products.reduce((s,p)=>s+p.stock*p.cost,0),cons=data.movements.filter(m=>m.type==='salida').reduce((s,m)=>s+m.qty*m.cost,0);return head('Reportes y costos','Indicadores de existencias y consumo de materiales.',btn('Inventario CSV','csv-products')+btn('Movimientos CSV','csv-moves'))+`<div class="metrics">${[['Valor actual',money(val)],['Salidas registradas',money(cons)],['Materiales registrados',fmt(data.products.length)],['Materiales críticos',fmt(data.products.filter(p=>p.stock<=p.min).length)]].map(([k,v])=>`<div class="panel metric"><div><div class="metric-label">${k}</div><strong>${v}</strong></div></div>`).join('')}</div><div class="panel"><h2>Valor por categoría</h2><p>Existencias × costo unitario registrado.</p>${categories.map(c=>[c,data.products.filter(p=>p.category===c).reduce((s,p)=>s+p.stock*p.cost,0)]).filter(x=>x[1]>0).map(([c,v])=>`<div class="bar-row" style="grid-template-columns:100px 1fr minmax(85px,auto)"><b>${esc(c)}</b><div class="bar-track"><div class="bar-fill" style="width:${v/Math.max(val,1)*100}%"></div></div><b>${money(v)}</b></div>`).join('')}</div>`}
function settings(){return head('Configuración','Administra la información del piloto y tus copias de seguridad.')+`<div class="grid"><div class="panel"><h2>Datos del sistema</h2><p>${serverMode?'La información se almacena en una base SQLite centralizada. Los equipos conectados al mismo servidor consultan las mismas existencias.':'Esta demostración guarda información localmente, en este navegador. No hay sincronización automática entre celulares o computadoras.'}</p><div class="notice">${serverMode?'Exporta una copia JSON antes de restaurar o reemplazar el inventario. La base de datos del taller original no se modifica.':'Para transferir datos a otro dispositivo, exporta la copia JSON e impórtala allí. No uses este piloto como única copia de inventario real.'}</div><div class="actions">${btn('Exportar copia JSON','backup','')}${btn('Importar copia','import')}</div></div><div class="panel"><h2>Datos de demostración</h2><p>${serverMode?'Estas acciones reemplazan el inventario compartido de todos los equipos conectados. Exporta primero una copia.':'Restablece las existencias de prueba o empieza con un catálogo vacío.'}</p><div class="actions section-gap">${btn('Restablecer demo','reset','danger')}${btn('Vaciar datos','clear','danger')}</div></div></div>`}
function modal(title,html){formRevision=serverRevision;const first=$('#overlay').hidden;if(first)modalActivator=document.activeElement;$('#modal-title').textContent=title;$('#modal-body').innerHTML=html;$('#overlay').hidden=false;document.body.style.overflow='hidden';$('#main').inert=true;$('#sidebar').inert=true;$('#close').focus({preventScroll:true});document.dispatchEvent(new CustomEvent('tinta:modal',{detail:{first}}))}
async function stopScan(){scannerEpoch++;const s=scanner;scanner=null;scanBusy=false;if(s){try{if(s.isScanning)await s.stop()}catch{}try{s.clear()}catch{}}}
function close(){if(mutationPending)return;stopScan();$('#overlay').hidden=true;document.body.style.overflow='';$('#modal-body').innerHTML='';$('#main').inert=false;$('#sidebar').inert=false;if(deferredRender){deferredRender=false;render()}if(modalActivator?.isConnected&&getComputedStyle(modalActivator).visibility!=='hidden'&&modalActivator.getClientRects().length)modalActivator.focus({preventScroll:true});else $('#main').focus({preventScroll:true});modalActivator=null}
const field=(label,name,value='',attrs='',type='text')=>`<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${attrs}></label>`;const selectField=(label,name,opts)=>`<label class="field">${label}<select name="${name}">${opts}</select></label>`;const footerForm=(text='Guardar')=>`<div class="form-actions">${btn('Cancelar','close')}<button type="submit" class="button">${text}</button></div>`;const form=(name,body,text)=>`<form id="${name}">${body}${footerForm(text)}</form>`;const fd=e=>Object.fromEntries(new FormData(e.target).entries());
function nextCode(){let n=1;while(data.products.some(p=>p.code==='MAT-'+String(n).padStart(4,'0')))n++;return 'MAT-'+String(n).padStart(4,'0')}
function productForm(p={},suggested=''){let edit=!!p.id; modal(edit?'Editar material':'Nuevo material',form('product-form',`<div class="form-grid">${field('Código único','code',p.code||suggested||nextCode(),'required maxlength="48" pattern="[ -~]+"')}${field('Nombre del material','name',p.name,'required maxlength="120"')}${selectField('Categoría','category',options(categories,p.category||'Papel'))}${selectField('Unidad de medida','unit',options(units,p.unit||'unidades'))}${field('Dimensiones / especificación','detail',p.detail,'maxlength="120" placeholder="Ej. 1,52 m de ancho"')}${field('Ubicación','location',p.location,'maxlength="50" placeholder="Ej. B-01"')}${field(edit?'Stock actual (ajustar en movimientos)':'Stock inicial','stock',p.stock??0,`min="0" step="0.001" required ${edit?'readonly':''}`,'number')}${field('Stock mínimo','min',p.min??0,'min="0" step="0.001" required','number')}${finance()?field('Costo por unidad (Bs)','cost',p.cost??0,'min="0" step="0.01" required','number'):'<input type="hidden" name="cost" value="0">'}${selectField('Proveedor','supplier','<option value="">Sin proveedor</option>'+options([...new Set([...data.suppliers.map(s=>s.name),...(p.supplier?[p.supplier]:[])])],p.supplier))}</div><div class="notice">Puedes usar el código interno generado o el código original del fabricante. Cada rollo o sobrante puede tener un código propio.</div>`,'Guardar material'));$('#product-form').addEventListener('submit',async e=>{e.preventDefault();let v=fd(e);v.code=v.code.trim();v.name=v.name.trim();if(!v.name||!v.code)return toast('Completa el nombre y código.');if(data.products.some(x=>x.code.toLowerCase()===v.code.toLowerCase()&&x.id!==p.id))return toast('Ese código ya está registrado.');for(const k of ['stock','min','cost'])v[k]=Number(v[k]);if(serverMode){if(await apiWrite(edit?'products/'+encodeURIComponent(p.id):'products',edit?'PUT':'POST',v,formRevision)){close();go('inventory');toast('Material guardado en el servidor.')}return}if(edit){Object.assign(p,v)}else{p={...v,id:id()};data.products.push(p);if(p.stock>0)record(p,'entrada',p.stock,'Stock inicial','','Operador')}save();close();go('inventory');toast('Material guardado.');})}
function record(p,type,qty,note,order,operator){data.movements.unshift({id:id(),productId:p.id,code:p.code,name:p.name,type,qty,unit:p.unit,cost:p.cost,when:now(),note,order,operator})}
function detail(p){if(!p)return;modal('Ficha del material',`<div class="panel product-detail"><span class="code">${esc(p.code)}</span><h2 class="section-gap">${esc(p.name)}</h2><p>${esc(p.category)} · ${esc(p.detail)}</p><div class="big-number">${fmt(p.stock)} ${esc(p.unit)}</div>${badge(p)}<p class="section-gap">Ubicación: <b>${esc(p.location||'Sin asignar')}</b><br>Proveedor: ${esc(p.supplier||'Sin asignar')}<br>Mínimo: ${fmt(p.min)} ${esc(p.unit)}${finance()?`<br>Costo unitario: ${money(p.cost)}`:''}</p></div><div class="actions section-gap">${serverMode&&role()==='produccion'?btn('Retirar material','exit','',`data-id="${esc(p.id)}"`)+btn('Devolver material','return','secondary',`data-id="${esc(p.id)}"`):serverMode&&role()==='almacen'?btn('Entrada','entry','',`data-id="${esc(p.id)}"`)+btn('Salida','exit','secondary',`data-id="${esc(p.id)}"`)+btn('Otros movimientos','move','secondary',`data-id="${esc(p.id)}"`):btn('Registrar movimiento','move','',`data-id="${esc(p.id)}"`)}${btn('Editar','edit-product','secondary',`data-id="${esc(p.id)}"`)}${btn('Etiqueta','one-label','secondary',`data-id="${esc(p.id)}"`)}${btn('Crear sobrante','remnant','secondary',`data-id="${esc(p.id)}"`)}</div><div class="section-gap"><h3>Últimos movimientos</h3>${movementRows(data.movements.filter(m=>m.productId===p.id).slice(0,4))}</div>`)}
function movementForm(pid='',type='entrada',order=''){if(!moveRole())return;if(role()==='produccion'&&!['salida','devolucion'].includes(type))type='salida';if(!data.products.length){toast('Primero registra un material.');if(stockRole())productForm();return}modal('Registrar movimiento',form('movement-form',`<div class="form-grid">${selectField('Material','productId',productOptions(pid))}${selectField('Tipo de movimiento','type',(role()==='produccion'?['salida','devolucion']:['entrada','salida','devolucion','ajuste','traslado']).map(t=>`<option value="${t}" ${t===type?'selected':''}>${typeName(t)}</option>`).join(''))}<div class="full notice" id="move-info"></div><div id="quantity-field">${field('Cantidad','qty',1,'min="0.001" step="0.001" required','number')}</div><div id="location-field" hidden>${field('Nueva ubicación','location','','maxlength="50"')}</div>${selectField('Orden de trabajo (opcional)','order',orderOptions(order))}${serverMode?'':field('Responsable','operator','Operador','required maxlength="60"')}<details class="optional-note full"><summary>Agregar nota (opcional)</summary><label class="field">Nota / motivo<textarea name="note" placeholder="Ej. recepción de compra, impresión de una orden"></textarea></label></details></div>`,'Confirmar movimiento'));const f=$('#movement-form');function update(){let p=data.products.find(x=>x.id===f.elements.productId.value);let t=f.elements.type.value;$('#move-info').textContent=`Stock actual: ${fmt(p.stock)} ${p.unit} · Ubicación: ${p.location||'Sin asignar'}${t==='ajuste'?' · Ingresa el nuevo saldo total.':''}`;$('#quantity-field').hidden=t==='traslado';f.elements.qty.required=t!=='traslado';f.elements.qty.min=t==='ajuste'?'0':'0.001';$('#location-field').hidden=t!=='traslado';f.elements.location.required=t==='traslado';}f.elements.productId.onchange=update;f.elements.type.onchange=update;update();f.onsubmit=async e=>{e.preventDefault();const v=fd(e);if(serverMode){v.qty=v.type==='traslado'?0:Number(v.qty);if(await apiWrite('movements','POST',v,formRevision)){close();render();toast('Movimiento registrado. Stock compartido actualizado.')}return}let p=data.products.find(x=>x.id===v.productId),q=Number(v.qty),t=v.type,old=p.stock;let note=v.note.trim();if(t==='traslado'){if(!v.location.trim())return toast('Ingresa una ubicación.');note=`${p.location||'Sin asignar'} → ${v.location.trim()}. ${note}`;p.location=v.location.trim();q=0}else if(t==='ajuste'){if(q<0||!Number.isFinite(q))return toast('Cantidad inválida.');p.stock=round(q);note=`Saldo anterior: ${fmt(old)}; nuevo saldo: ${fmt(p.stock)}. ${note}`}else{if(!Number.isFinite(q)||q<=0)return toast('Ingresa una cantidad válida.');if(['salida','merma'].includes(t)){if(q>p.stock)return toast('Stock insuficiente.');p.stock=round(p.stock-q)}else p.stock=round(p.stock+q)}record(p,t,q,note,v.order,v.operator.trim());save();close();render();toast('Movimiento registrado. Stock actualizado.')}}
function remnantForm(p){modal('Registrar sobrante',form('remnant-form',`<p>Divide una parte del stock de ${esc(p.name)} y genera un material independiente con su propia etiqueta, conservando el saldo total.</p><div class="form-grid section-gap">${field('Nuevo código','code',nextCode(),'required maxlength="48" pattern="[ -~]+"')}${field('Cantidad a separar ('+esc(p.unit)+')','qty',0,`min="0.001" max="${p.stock}" step="0.001" required`,'number')}${field('Descripción del sobrante','detail','','required placeholder="Ej. 50 × 80 cm"')}${field('Ubicación','location',p.location,'required')}</div>`,'Crear sobrante'));$('#remnant-form').onsubmit=async e=>{e.preventDefault();let v=fd(e),q=Number(v.qty);if(serverMode){v.qty=q;if(await apiWrite('products/'+encodeURIComponent(p.id)+'/remnants','POST',v,formRevision)){const np=data.products.find(x=>x.code.toLowerCase()===v.code.trim().toLowerCase());close();go('inventory');toast('Sobrante creado en el servidor.');if(np)detail(np)}return}if(data.products.some(x=>x.code.toLowerCase()===v.code.trim().toLowerCase()))return toast('Código duplicado.');if(q<=0||q>p.stock)return toast('Cantidad no disponible.');let np={...p,id:id(),code:v.code.trim(),name:p.name+' · Sobrante',detail:v.detail.trim(),location:v.location.trim(),stock:q,min:0};p.stock=round(p.stock-q);data.products.push(np);record(p,'ajuste',p.stock,`Separación ${fmt(q)} ${p.unit} hacia ${np.code}`,'','Operador');record(np,'entrada',q,`Sobrante de ${p.code}`,'','Operador');save();close();go('inventory');toast('Sobrante creado. Genera su etiqueta.');detail(np)}}
function orderForm(o={}){let n=1;while(data.orders.some(x=>x.code==='OT-'+String(n).padStart(3,'0')))n++;modal(o.id?'Editar orden':'Nueva orden',form('order-form',`<div class="form-grid">${field('Código','code',o.code||'OT-'+String(n).padStart(3,'0'),`required ${o.id?'readonly':''}`)}${field('Trabajo','name',o.name,'required')}${field('Cliente','client',o.client)}${selectField('Estado','state',options(['Pendiente','En producción','Finalizada'],o.state||'Pendiente'))}${field('Presupuesto de materiales (Bs)','budget',o.budget??0,'min="0" step="0.01" required','number')}</div>`,'Guardar orden'));$('#order-form').onsubmit=async e=>{e.preventDefault();let v=fd(e);v.code=v.code.trim();if(data.orders.some(x=>x.code===v.code&&x.id!==o.id))return toast('Código de orden duplicado.');v.budget=Number(v.budget);if(serverMode){if(await apiWrite(o.id?'orders/'+encodeURIComponent(o.id):'orders',o.id?'PUT':'POST',v,formRevision)){close();render();toast('Orden guardada en el servidor.')}return}if(o.id)Object.assign(o,v);else data.orders.push({...v,id:id()});save();close();render();toast('Orden guardada.')}}
function supplierForm(s={}){modal(s.id?'Editar proveedor':'Nuevo proveedor',form('supplier-form',`<div class="form-grid">${field('Nombre','name',s.name,'required')}${field('Teléfono','phone',s.phone)}${field('Correo','email',s.email,'','email')}<label class="field full">Notas<textarea name="notes">${esc(s.notes)}</textarea></label></div>`,'Guardar proveedor'));$('#supplier-form').onsubmit=async e=>{e.preventDefault();let v=fd(e);v.name=v.name.trim();if(!v.name)return toast('Ingresa el nombre.');if(data.suppliers.some(x=>x.name.toLowerCase()===v.name.toLowerCase()&&x.id!==s.id))return toast('Ya existe ese proveedor.');if(serverMode){if(await apiWrite(s.id?'suppliers/'+encodeURIComponent(s.id):'suppliers',s.id?'PUT':'POST',v,formRevision)){close();render();toast('Proveedor guardado en el servidor.')}return}if(s.id){data.products.filter(p=>p.supplier===s.name).forEach(p=>p.supplier=v.name);Object.assign(s,v)}else data.suppliers.push({...v,id:id()});save();close();render();toast('Proveedor guardado.')}}
function openScan(){stopScan();modal('Escanear material',`<p>Apunta la cámara trasera al código de barras o QR. También puedes escribir el código o usar un lector USB.</p><div class="scanner-box"><div id="reader"><div class="scan-target">${ico('scan',58)}</div></div></div><div class="actions">${btn('Activar cámara','start-camera','')}${btn('Detener cámara','stop-camera')}</div><p id="scan-status" class="section-gap" style="font-size:14px">La cámara necesita permiso del navegador.</p><form id="scan-form" class="section-gap"><label class="field">Código del material<input name="code" placeholder="Ej. VIN-001" required autocomplete="off" autocapitalize="off"></label><button class="button" type="submit">Buscar código</button></form><div class="notice">Prueba con el código VIN-001 o imprime una etiqueta y escanéala desde tu celular.</div>`);$('#scan-form').onsubmit=e=>{e.preventDefault();handleScan(fd(e).code)}}
function handleScan(code){code=String(code).trim();if(!code)return;let p=data.products.find(x=>x.code.toLowerCase()===code.toLowerCase());stopScan();if(p){detail(p);toast('Código reconocido: '+p.code)}else{modal('Código no registrado',`<div class="notice warn">No se encontró <b>${esc(code)}</b> en el catálogo.</div><p>${stockRole()?'Puedes asociarlo a un material nuevo o volver a escanear.':'Solicita al almacén que registre el material o vuelve a escanear.'}</p><div class="actions section-gap">${btn('Nuevo material','create-scanned','',`data-code="${esc(code)}"`)}${btn('Escanear de nuevo','scan')}</div>`)}}
async function startCamera(){if(scanBusy||scanner?.isScanning)return;const st=$('#scan-status');if(!navigator.mediaDevices?.getUserMedia){st.textContent='La cámara requiere HTTPS y un navegador compatible. Usa el ingreso manual.';return}scanBusy=true;const epoch=++scannerEpoch;st.textContent='Solicitando permiso de cámara…';$('#reader').innerHTML='';let s;try{s=new Html5Qrcode('reader',{formatsToSupport:[Html5QrcodeSupportedFormats.QR_CODE,Html5QrcodeSupportedFormats.CODE_128,Html5QrcodeSupportedFormats.EAN_13,Html5QrcodeSupportedFormats.EAN_8,Html5QrcodeSupportedFormats.CODE_39,Html5QrcodeSupportedFormats.UPC_A,Html5QrcodeSupportedFormats.UPC_E],verbose:false});scanner=s;await s.start({facingMode:'environment'},{fps:10,qrbox:(w,h)=>({width:Math.min(Math.floor(w*.9),330),height:Math.min(Math.floor(h*.7),190)})},code=>{if(epoch===scannerEpoch)handleScan(code)},()=>{});if(epoch!==scannerEpoch){if(s.isScanning)await s.stop(); return}st.textContent='Cámara activa. Centra el código con buena iluminación.';}catch(e){if(epoch===scannerEpoch){st.textContent='No se pudo iniciar la cámara. Revisa los permisos o usa el código manual.';try{s?.clear()}catch{}scanner=null}}finally{if(epoch===scannerEpoch)scanBusy=false}}
function download(filename,content,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000)}
function csv(rows){return '\ufeff'+rows.map(r=>r.map(v=>'"'+String(v??'').replace(/^[=+\-@\t\r]/,"'$&").replaceAll('"','""')+'"').join(';')).join('\r\n')}
function validBackup(v){return v&&['products','movements','orders','suppliers'].every(k=>Array.isArray(v[k]))&&v.products.every(p=>p&&typeof p.id==='string'&&typeof p.name==='string'&&typeof p.code==='string'&&typeof p.unit==='string'&&['stock','min','cost'].every(k=>typeof p[k]==='number'&&Number.isFinite(p[k])&&p[k]>=0))&&new Set(v.products.map(p=>p.code.toLowerCase())).size===v.products.length&&new Set(v.products.map(p=>p.id)).size===v.products.length&&v.movements.every(m=>m&&typeof m.when==='string'&&Number.isFinite(Date.parse(m.when))&&typeof m.qty==='number'&&Number.isFinite(m.qty)&&typeof m.cost==='number'&&Number.isFinite(m.cost))&&v.orders.every(o=>o&&typeof o.id==='string'&&typeof o.code==='string'&&typeof o.name==='string'&&typeof o.budget==='number')&&v.suppliers.every(s=>s&&typeof s.id==='string'&&typeof s.name==='string')}
$('#import-file').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;try{const v=JSON.parse(await f.text());if(!validBackup(v))throw new Error('Formato incorrecto');if(confirm(serverMode?'¿Reemplazar el inventario compartido de todos los dispositivos con esta copia?':'¿Reemplazar los datos actuales con esta copia?')){if(serverMode){if(await apiWrite('backup/restore','PUT',v)){labelIds.clear();render();toast('Copia importada en SQLite.')}}else{data=v;labelIds.clear();save();render();toast('Copia importada.')}}}catch{toast('Archivo inválido. Usa una copia JSON de TintaStock.')}e.target.value=''});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-go],[data-action]');if(!b)return;if(serverMode&&mutationPending)return;if(b.dataset.go){go(b.dataset.go);return}let a=b.dataset.action;if(!canAction(a))return;const account=$('#account');if(account?.open)account.open=false;let p=data.products.find(x=>x.id===b.dataset.id),o=data.orders.find(x=>x.id===b.dataset.id),s=data.suppliers.find(x=>x.id===b.dataset.id);switch(a){case 'quick-inventory':go('inventory');break;case 'return':movementForm(p?.id,'devolucion');break;case 'new-user':userForm();break;case 'edit-user':userForm(usersData.find(u=>u.id===b.dataset.id));break;case 'logout':await logoutUser();break;case 'password':passwordForm();break;case 'close':close();break;case 'scan':openScan();break;case 'start-camera':startCamera();break;case 'stop-camera':stopScan().then(()=>{if($('#scan-status'))$('#scan-status').textContent='Cámara detenida.'});break;case 'new-product':productForm();break;case 'edit-product':productForm(p);break;case 'create-scanned':productForm({},b.dataset.code);break;case 'detail':detail(p);break;case 'move':movementForm(p?.id);break;case 'entry':movementForm(p?.id,'entrada');break;case 'exit':movementForm(p?.id,'salida');break;case 'remnant':remnantForm(p);break;case 'clear-filters':search='';cat='';status='';render();$('#search')?.focus();break;case 'show-low':status='Alerta';search='';cat='';go('inventory');break;case 'go-labels':go('labels');break;case 'one-label':labelIds=new Set([p.id]);close();go('labels');break;case 'label-all':labelIds=labelIds.size===data.products.length?new Set():new Set(data.products.map(p=>p.id));render();break;case 'print':if(!labelIds.size)return toast('Selecciona un material.');if(labelIds.size*labelQty>600)return toast('Imprime en lotes de hasta 600 etiquetas.');labelElements($('#print-sheet'),600);setTimeout(()=>window.print(),250);break;case 'new-order':orderForm();break;case 'edit-order':orderForm(o);break;case 'order-use':movementForm('','salida',o.code);break;case 'new-supplier':supplierForm();break;case 'edit-supplier':supplierForm(s);break;case 'csv-products':download('inventario.csv',csv([['Código','Nombre','Categoría','Detalle','Unidad','Stock','Mínimo','Costo Bs','Ubicación','Proveedor'],...data.products.map(p=>[p.code,p.name,p.category,p.detail,p.unit,p.stock,p.min,p.cost,p.location,p.supplier])]),'text/csv;charset=utf-8');break;case 'csv-moves':download('movimientos.csv',csv([['Fecha','Tipo','Código','Material','Cantidad','Unidad','Orden','Responsable','Nota'],...data.movements.map(m=>[m.when,typeName(m.type),m.code,m.name,m.qty,m.unit,m.order,m.operator,m.note])]),'text/csv;charset=utf-8');break;case 'backup':download('tintastock-copia.json',JSON.stringify(data,null,2),'application/json');break;case 'import':$('#import-file').click();break;case 'reset':case 'clear':if(confirm(serverMode?'¿Reemplazar TODOS los datos del servidor compartido? Exporta primero una copia.':'¿Reemplazar todos los datos locales? Exporta una copia antes si los necesitas.')){const next=a==='reset'?seed():emptyData();if(serverMode){if(await apiWrite('backup/restore','PUT',next)){labelIds.clear();go('home');toast('Inventario del servidor actualizado.')}}else{data=next;labelIds.clear();save();go('home');toast('Datos actualizados.')}}break;}});
document.addEventListener('input',e=>{if(e.target.id==='search'){search=e.target.value;$('#inventory-table').innerHTML=inventoryTable()}});document.addEventListener('change',e=>{const t=e.target;if(t.id==='category'){cat=t.value;$('#inventory-table').innerHTML=inventoryTable()}if(t.id==='status'){status=t.value;$('#inventory-table').innerHTML=inventoryTable()}if(t.id==='move-filter'){moveFilter=t.value;render()}if(t.classList.contains('label-check')){t.checked?labelIds.add(t.value):labelIds.delete(t.value);drawLabels()}if(t.id==='label-type'){labelType=t.value;drawLabels()}if(t.id==='label-size'){labelSize=t.value;drawLabels()}if(t.id==='label-qty'){labelQty=Math.max(1,Math.min(30,Math.floor(Number(t.value)||1)));t.value=labelQty;drawLabels()}});
$('#close').onclick=close;$('#overlay').onclick=e=>{if(e.target===$('#overlay'))close()};
document.addEventListener('click',e=>{if(e.target.closest('#nav-more')){const b=$('#nav-more'),open=b.getAttribute('aria-expanded')!=='true';b.setAttribute('aria-expanded',String(open));$('#nav-secondary').classList.toggle('open',open);return}if(!e.target.closest('#nav')){const b=$('#nav-more');if(b){b.setAttribute('aria-expanded','false');$('#nav-secondary').classList.remove('open')}}if($('#sidebar').classList.contains('open')&&!e.target.closest('#sidebar,#menu'))closeMenu()});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){const wasMenu=$('#sidebar').classList.contains('open'),wasMore=$('#nav-more')?.getAttribute('aria-expanded')==='true';closeMenu();if(!$('#overlay').hidden)close();else if(wasMenu)$('#menu').focus();else if(wasMore)$('#nav-more').focus()}if(e.key==='Tab'&&!$('#overlay').hidden){const focusable=$$('.modal button:not([disabled]),.modal input:not([disabled]),.modal select:not([disabled]),.modal textarea:not([disabled]),.modal a[href]').filter(x=>x.getClientRects().length);if(!focusable.length)return;let first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
function authError(message=''){const e=$('#auth-error');e.hidden=!message;e.textContent=message}
async function authRequest(path,method='GET',payload){const options={method,cache:'no-store',credentials:'same-origin',headers:{'X-TintaStock-Client':'1'},signal:AbortSignal.timeout(15000)};if(payload!==undefined){options.headers['Content-Type']='application/json';options.body=JSON.stringify(payload)}const response=await fetch('./api/'+path,options);const result=await response.json();if(!response.ok){const err=Error(typeof result.detail==='string'?result.detail:(Array.isArray(result.detail)?result.detail.map(x=>`${x.loc?.at(-1)||'campo'}: ${x.msg}`).join(' · '):'No se pudo completar la solicitud.'));err.status=response.status;throw err}return result}
function sessionEnded(message=''){authEpoch++;refreshPending=false;usersLoading=false;currentUser=null;serverRevision=null;formRevision=null;data=emptyData();usersData=[];labelIds.clear();search='';cat='';status='';moveFilter='';$('#print-sheet').innerHTML='';$('#import-file').value='';$('#toast').classList.remove('show');$('#toast').textContent='';stopScan();mutationPending=false;deferredRender=false;$('#overlay').hidden=true;$('#modal-body').innerHTML='';$('#main').inert=false;$('#sidebar').inert=false;document.body.style.overflow='';$('#account').hidden=true;$('#account').open=false;$('#nav').innerHTML='';$('#page').innerHTML='';screen='home';lastRendered='';document.documentElement.dataset.auth='required';$('#auth-gate').hidden=false;$('#login-form').reset();authError(message);$('#login-form input[name=username]').focus()}
function setUser(user){authEpoch++;refreshPending=false;usersLoading=false;currentUser=user;data=emptyData();serverRevision=null;screen='home';lastRendered='';usersData=[];labelIds.clear();$('#account').hidden=false;$('#demo-avatar').hidden=true;$('#account-name').textContent=user.displayName;$('#account-role').textContent=ROLES[user.role];$('#account-avatar').textContent=user.displayName.split(/\s+/).map(s=>s[0]).slice(0,2).join('').toUpperCase();$('#account-user').textContent='@'+user.username+' · '+ROLES[user.role];$('#auth-gate').hidden=true;$('#setup-info').hidden=true;delete document.documentElement.dataset.auth;$('#login-form').reset();render();setConnection('loading','Conectando con el inventario…');refreshServer(true)}
async function initAuth(){try{const user=await authRequest('auth/me');setUser(user)}catch(e){sessionEnded(e.status===401?'':'No se pudo conectar con el servidor. Reintenta.');try{const state=await authRequest('auth/status');$('#setup-info').hidden=!state.setupRequired}catch{}}}
$('#login-form').addEventListener('submit',async e=>{e.preventDefault();if(!serverMode)return;const f=e.target,button=f.querySelector('button');button.disabled=true;authError();try{const user=await authRequest('auth/login','POST',Object.fromEntries(new FormData(f)));setUser(user)}catch(e){authError(e.status?e.message:'No se pudo conectar con el servidor.');f.elements.password.value='';f.elements.password.focus()}finally{button.disabled=false}});
async function logoutUser(){try{await authRequest('auth/logout','POST');sessionEnded('Sesión cerrada.')}catch{toast('No se pudo confirmar el cierre de sesión. Reintenta.')}}
function passwordForm(){modal('Cambiar contraseña',form('password-form',`${field('Contraseña actual','currentPassword','','required autocomplete="current-password"','password')}${field('Nueva contraseña','newPassword','','required minlength="10" maxlength="128" autocomplete="new-password"','password')}<p>Usa al menos 10 caracteres. Después inicia sesión con la contraseña nueva.</p>`,'Cambiar contraseña'));$('#password-form').onsubmit=async e=>{e.preventDefault();const f=e.target,button=f.querySelector('button[type=submit]');button.disabled=true;try{await authRequest('auth/password','POST',fd(e));sessionEnded('Contraseña actualizada. Inicia sesión nuevamente.')}catch(e){if(e.status===401)sessionEnded(e.message);else toast(e.message)}finally{button.disabled=false}}}
function userRows(){return usersData.length?`<div class="table-wrap"><table class="table user-table"><thead><tr><th>Nombre</th><th>Usuario</th><th>Rol</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>${usersData.map(u=>`<tr><td class="name"><b>${esc(u.displayName)}</b></td><td class="code">${esc(u.username)}</td><td>${esc(ROLES[u.role])}</td><td><span class="badge ${u.active?'':'out'}">${u.active?'Activo':'Desactivado'}</span></td><td><div class="row-actions">${btn('Editar','edit-user','small secondary',`data-id="${esc(u.id)}"`)}</div></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No hay cuentas para mostrar.</div>'}
function users(){return head('Gestor de usuarios','Cada operario utiliza su propia cuenta y sus permisos.',btn(ico('plus')+' Nuevo usuario','new-user',''))+`<div class="panel"><div id="users-list">${usersLoading?'<p>Cargando usuarios…</p>':userRows()}</div></div>`}
async function loadUsers(){if(role()!=='administracion'||usersLoading)return;usersLoading=true;const epoch=authEpoch;try{const rows=await authRequest('users');if(epoch!==authEpoch)return;usersData=rows;if(screen==='users'&&$('#users-list'))$('#users-list').innerHTML=userRows()}catch(e){if(epoch===authEpoch){if(e.status===401)sessionEnded(e.message);else toast(e.message)}}finally{if(epoch===authEpoch)usersLoading=false}}
function userForm(u={}){if(!u)u={};const edit=!!u.id;modal(edit?'Editar usuario':'Nuevo usuario',form('user-form',`<div class="form-grid">${field('Nombre visible','displayName',u.displayName,'required maxlength="120"')}${field('Usuario','username',u.username,'required minlength="3" maxlength="40" autocomplete="off"')}${selectField('Rol','role',Object.entries(ROLES).map(([k,v])=>`<option value="${k}" ${k===(u.role||'almacen')?'selected':''}>${v}</option>`).join(''))}${selectField('Estado','active',`<option value="true" ${u.active!==false?'selected':''}>Activo</option><option value="false" ${u.active===false?'selected':''}>Desactivado</option>`)}${field(edit?'Nueva contraseña (opcional)':'Contraseña inicial','password','',`${edit?'':'required'} minlength="10" maxlength="128" autocomplete="new-password"`,'password')}</div><div class="notice">${edit?'Si cambias la cuenta, sus sesiones se cerrarán y el usuario deberá entrar nuevamente.':'Crea una contraseña de al menos 10 caracteres y compártela de forma privada con el operario.'}</div>`,'Guardar usuario'));$('#user-form').onsubmit=async e=>{e.preventDefault();const f=e.target,button=f.querySelector('button[type=submit]');button.disabled=true;const v=fd(e);v.active=v.active==='true';if(!v.password)delete v.password;try{await authRequest(edit?'users/'+encodeURIComponent(u.id):'users',edit?'PUT':'POST',v);if(edit&&u.id===currentUser?.id){sessionEnded('Cuenta actualizada. Inicia sesión nuevamente.');return}close();await loadUsers();toast('Usuario guardado.')}catch(e){if(e.status===401)sessionEnded(e.message);else toast(e.message)}finally{button.disabled=false}}}
$('#drawer-backdrop').onclick=()=>{closeMenu();$('#menu').focus()};$('#drawer-close').onclick=()=>{closeMenu();$('#menu').focus()};
$('#menu').onclick=()=>{const open=$('#sidebar').classList.toggle('open');$('#drawer-backdrop').hidden=!open;$('#menu').setAttribute('aria-expanded',String(open));$('#menu').setAttribute('aria-label',open?'Cerrar menú':'Abrir menú');if(open)$('#drawer-close').focus({preventScroll:true})};$('#today').textContent=new Date().toLocaleDateString('es-BO',{day:'numeric',month:'long',year:'numeric',timeZone:'America/La_Paz'});render();if(serverMode){if('serviceWorker'in navigator){navigator.serviceWorker.getRegistrations().then(rs=>Promise.all(rs.filter(r=>r.active?.scriptURL===new URL('./sw.js',location.href).href||r.waiting?.scriptURL===new URL('./sw.js',location.href).href).map(r=>r.unregister()))).catch(()=>{})}initAuth();setInterval(()=>refreshServer(),10000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshServer()});window.addEventListener('online',()=>refreshServer(true));window.addEventListener('offline',()=>setConnection('offline','Sin conexión. Los cambios solo se guardan mediante el servidor.'));}else if('serviceWorker'in navigator){navigator.serviceWorker.register('./sw.js').catch(()=>{})}
